UPDATE companies SET description='LWI Metal Works was founded in 1969 by Leo Trombley as a small welding and repair shop in Morrisville, Vermont. The family-owned business is now headquartered in Morristown, Vermont, and has grown into a regional partner for structural steel fabrication, custom metalwork, and food-grade tank repair.

The company operates as an AISC-Certified Fabricator, providing structural steel packages ranging from single beams to several hundred tons for general contractors and local builders. Its miscellaneous metals shop produces egress stairs, decorative stairs, spiral stairs, handrails, and guardrails. A custom fabrication shop handles small production runs and one-off equipment repairs, while a dedicated tank shop services food-grade tanks and trailers for the region’s largest dairy haulers, performing accident repairs, suspension upgrades, and retrofits. A full-service machine shop with CNC mills and lathes supports prototyping, reverse engineering, and short-run production. The firm also offers design-build services covering permitting, engineering, design, fabrication, and erection, and holds rights to manufacture Lane & Chase sawmill replacement parts.

LWI serves commercial construction, dairy transportation, and sawmill industries. Structural and miscellaneous steel packages go to national general contractors and local builders. The tank repair division works with the region’s largest dairy haulers. The sawmill parts line supplies Lane & Chase equipment owners. Machine shop and custom fabrication services support industrial clients needing prototypes, repair, or short-run production.

The company cites its AISC certification and an American Welding Society certified instructor on staff as quality markers. Housing structural and miscellaneous fabrication under one roof is intended to reduce cost and schedule risk. Its design-build approach is offered as a more flexible alternative to pre-engineered steel buildings.', certifications=ARRAY['AISC Certified Fabricator']::text[], profile='{"capabilities": ["Structural steel fabrication", "Miscellaneous metals fabrication (egress stairs, decorative stairs, spiral stairs, handrails, guardrails)", "Custom metal fabrication (small production runs, one-off equipment repair)", "Food-grade tank and trailer repair (accident repair, suspension upgrades, tank retrofits)", "CNC milling", "CNC turning", "Prototyping", "Reverse engineering", "Design-build (permitting, engineering, design, fabrication, erection)", "Sawmill parts manufacturing (Lane & Chase)", "Welding and repair"], "industries": ["Commercial construction", "Dairy transportation", "Sawmill", "General industrial fabrication"], "materials": ["Steel"], "equipment": ["CNC mills", "CNC lathes"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["AISC-Certified Fabricator", "American Welding Society certified instructor on staff", "Structural and miscellaneous fabrication under one roof", "Design-build flexibility versus pre-engineered buildings", "Rights to manufacture Lane & Chase sawmill parts"], "facts_used": ["Founded 1969 by Leo Trombley in Morrisville, Vermont -> /", "Family-owned since 1969 -> /", "Headquartered in Morristown, Vermont -> db", "AISC-Certified Fabricator -> /", "American Welding Society certified instructor on staff -> /", "Structural steel fabrication up to several hundred tons -> /", "Miscellaneous metals: egress stairs, decorative stairs, spiral stairs, handrails, guardrails -> /", "Custom metalwork: small production runs, one-off equipment repair -> /", "Food-grade tank and trailer repair for largest dairy haulers in region -> /", "Machine shop with CNC mills and lathes for prototyping, reverse engineering, short-run production -> /", "Design-build services: permitting, engineering, design, fabrication, erection -> /", "Lane & Chase sawmill parts manufacturing rights -> /", "Serves commercial construction, dairy transportation, sawmill industries -> /", "Works with national general contractors and local builders -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "From structural and miscellaneous steel for building construction to prototype machining to tank trailer repair to custom metalwork, LWI is your partner. As an AISC-Certified Fabricator...", "founded_year": "1969", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='lwi-metal-works' AND approved AND profile IS NULL;
UPDATE companies SET description='Lake Erie Frozen Foods was founded in 1961 in Ashland, Ohio, about 60 miles south of Cleveland. The business has been family-owned and operated for more than 20 years, building a reputation around frozen appetizers for the restaurant and retail food sectors.

The company runs a 20,000-square-foot processing facility, half of which is USDA-inspected and equipped with two full stainless steel production lines. Daily output reaches roughly 20,000 pounds per shift, with sanitation managed to USDA and AIB standards. The product catalog spans approximately 100 items and package sizes, including breaded and battered specialties and a newer USDA-produced line featuring Reuben Bites, Philly Steak Bites, and Pizza Bites. Custom coating and packing services are offered for restaurant chains.

Lake Erie Frozen Foods sells through more than 250 distributors — among them Sysco, US Foods, Bellisimo, Unipro, PFG, and Nugget Houses — covering the 48 contiguous states, Canada, and Europe. Customers include both food-service operators and retail buyers, and the company works directly with chains to develop proprietary appetizer programs.

